    "submission/trojan_report.json"
  ],
  "expected_output": {
    "description": "A single JSON file at submission/trojan_report.json containing a trojan classification (trojan_present), lists of suspect gate-level instance names and net names implicated in the wiring anomaly, the name of the top-level output port vulnerable to a single-replica fault, a free-text root-cause explanation, and a confidence score.",
    "required_fields": [
      "trojan_present",
      "suspect_instances",
      "suspect_nets",
      "affected_output",
      "root_cause",
      "confidence"
    ]
  },
  "metrics": [
    {
      "name": "detection_rate",
