// tmr_voter_netlist.v
// Structural gate-level netlist for a triple-modular-redundancy (TMR) block.
// Three replica compute cells produce identical logic from shared primary
// inputs; a majority voter cell masks any single replica fault to produce
// the top-level output voted_out.

`timescale 1ns/1ps

// ---------------------------------------------------------------------
// replica_cell: small combinational logic block. Each replica instance
// computes the same function of the shared primary inputs.
// ---------------------------------------------------------------------
module replica_cell (
    input  wire in_a,
    input  wire in_b,
    input  wire in_c,
    output wire out_y
);
    wire n1, n2;

    and (n1, in_a, in_b);
    or  (n2, n1, in_c);
    buf (out_y, n2);

endmodule

// ---------------------------------------------------------------------
// wire_tap: single-input single-output buffering cell, used generically
// for signal routing/fanout regeneration within the block.
// ---------------------------------------------------------------------
module wire_tap (
    input  wire tap_in,
    output wire tap_out
);
    buf (tap_out, tap_in);
endmodule

// ---------------------------------------------------------------------
// voter3: standard 2-of-3 majority voter.
// voted_out = maj(voter_a, voter_b, voter_c)
// ---------------------------------------------------------------------
module voter3 (
    input  wire voter_a,
    input  wire voter_b,
    input  wire voter_c,
    output wire voted_out
);
    wire m1, m2, m3, m_or1, m_or2;

    and (m1, voter_a, voter_b);
    and (m2, voter_b, voter_c);
    and (m3, voter_a, voter_c);

    or  (m_or1, m1, m2);
    or  (m_or2, m_or1, m3);

    buf (voted_out, m_or2);

endmodule

// ---------------------------------------------------------------------
// tmr_top: top-level triple-modular-redundancy block.
// ---------------------------------------------------------------------
module tmr_top (
    input  wire a,
    input  wire b,
    input  wire c,
    output wire voted_out
);

    // Replica output nets.
    wire net_repa_out;
    wire net_repb_out;   // intended to drive voter_b; left dangling below
    wire net_repc_out;

    // Voter input nets.
    wire voter_a;
    wire voter_b;
    wire voter_c;

    // Buffered/routed signal used to feed voter_b.
    wire net_buf1_out;

    // Three replica instances, each computing the same function from the
    // shared primary inputs.
    replica_cell u_replica_a (
        .in_a  (a),
        .in_b  (b),
        .in_c  (c),
        .out_y (net_repa_out)
    );

    replica_cell u_replica_b (
        .in_a  (a),
        .in_b  (b),
        .in_c  (c),
        .out_y (net_repb_out)
    );

    replica_cell u_replica_c (
        .in_a  (a),
        .in_b  (b),
        .in_c  (c),
        .out_y (net_repc_out)
    );

    // Routing buffer feeding the second voter input.
    wire_tap u_buf1 (
        .tap_in  (net_repa_out),
        .tap_out (net_buf1_out)
    );

    // Voter input wiring.
    assign voter_a = net_repa_out;
    assign voter_b = net_buf1_out;
    assign voter_c = net_repc_out;

    // Majority voter instance.
    voter3 u_voter3 (
        .voter_a   (voter_a),
        .voter_b   (voter_b),
        .voter_c   (voter_c),
        .voted_out (voted_out)
    );

endmodule

// fault_harness_tb.v
// Compact single-stuck-at-fault harness for tmr_top.
//
// Drives a handful of representative input vectors through the design and
// reports the voted output for each. A single stuck-at fault can be
// injected into one replica under test at a time by selecting FAULT_REPLICA
// (0 = none, 1 = replica A, 2 = replica B, 3 = replica C) and FAULT_VALUE
// (the stuck-at logic value to force). The fault is applied via a
// hierarchical force on the replica's output net for the duration of the
// run, emulating a single stuck-at defect in that replica's logic cone.

`timescale 1ns/1ps

module fault_harness_tb;

    // Select which replica under test receives the injected fault, and to
    // what stuck-at value. 0 = no fault injected.
    parameter FAULT_REPLICA = 0;
    parameter FAULT_VALUE   = 1'b0;

    reg a, b, c;
    wire voted_out;

    integer i;
    reg [2:0] vec;

    tmr_top dut (
        .a         (a),
        .b         (b),
        .c         (c),
        .voted_out (voted_out)
    );

    // Apply the stuck-at fault (if any) to the selected replica's output
    // net under test. This mimics a single hardware fault local to one
    // replica's logic cone.
    initial begin
        #1;
        if (FAULT_REPLICA == 1)
            force dut.net_repa_out = FAULT_VALUE;
        else if (FAULT_REPLICA == 2)
            force dut.net_repb_out = FAULT_VALUE;
        else if (FAULT_REPLICA == 3)
            force dut.net_repc_out = FAULT_VALUE;
    end

    initial begin
        $display("FAULT_REPLICA=%0d FAULT_VALUE=%b", FAULT_REPLICA, FAULT_VALUE);
        $display(" a b c | voted_out");

        for (i = 0; i < 8; i = i + 1) begin
            vec = i[2:0];
            a = vec[2];
            b = vec[1];
            c = vec[0];
            #5;
            $display(" %b %b %b |    %b", a, b, c, voted_out);
        end

        $finish;
    end

endmodule
